unitsize (0.6 cm);

pair A, B, F;

F = (4,0);
A = (35/8,3*sqrt(15)/8);
B = (55/16,-9*sqrt(15)/16);

draw(xscale(5)*yscale(3)*Circle((0,0),1));
draw(A--B);
draw((-6,0)--(6,0));
draw((0,-4)--(0,4));

dot("$A$", A, NE);
dot("$B$", B, SE);
dot("$F$", F, NW);
[/asy] Please reason step by step, and put your final answer within \boxed{}.

